 private static List<Attached> attachments(IsoObject owner){var rows=owner.getAttachedAnimSprite();if(rows==null||rows.isEmpty())return List.of();if(rows.size()>16)throw new IllegalArgumentException("Counter attachments budget");var result=new ArrayList<Attached>();for(var row:rows){if(row==null||row.parentSprite==null)throw new IllegalArgumentException("Counter attachment identity");result.add(new Attached(new WeakReference<>(row),new WeakReference<>(row.parentSprite),row.parentSprite.name));}return List.copyOf(result);}
